        "A": "確保檢索到的文件能被完整納入語言模型的上下文視窗（Context",
        "B": "選擇使用Faiss 或ScaNN 等近似最近鄰搜尋函式庫；",
        "C": "降低嵌入模型（Embedding Model）在高維空間中的計算成本與記",
