      "options": {
        "A": "提高Query-Key 點積（Dot Product）的縮放常數；",
        "B": "在Softmax 前加入高斯雜訊（Gaussian Noise）；",
        "C": "使用 ReLU 函數取代 Softmax；",
        "D": "對注意力權重施加稀疏化約束（Sparsity Constraint）"
      },
      "answer": "A",
      "explanation": "正確答案是 A. 提高Query-Key 點積（Dot Product）的縮放常數；\n\n解析：\n🔹 A. 提高Query-Key 點積（Dot Product）的縮放常數； : 在 Transformer 的縮放點積注意力 (Scaled Dot-Product Attention) 機制中，如果點積數值過小，經過 Softmax 後機率分佈會趨於平緩 (即注意力分布過於平均)。適當改變 (例如調整) 縮放因子可以使 Softmax 輸出的機率分佈變得更尖銳，幫助模型聚焦於關鍵特徵。\n\n其他選項說明：\n🔹 B. 在Softmax 前加入高斯雜訊（Gaussian Noise）； : 加入雜訊通常會使分布更平滑，可能加劇注意力崩潰的問題。\n🔹 C. 使用 ReLU 函數取代 Softmax； : ReLU 輸出的不是機率分佈，無法直接取代 Softmax 進行注意力權重的計算。\n🔹 D. 對注意力權重施加稀疏化約束（Sparsity Constraint） : 雖然這是一種迫使模型聚焦的方法，但在標準 Transformer 架構中，調整縮放常數是更直接且底層的解決機制。"
