      "explanation": "正確答案是 B. 採用高效率的距離索引結構（Distance Index Structure），例如KD-Tree 或 Ball Tree；\n\n解析：\n🔹 B. 採用高效率的距離索引結構（Distance Index Structure），例如KD-Tree 或 Ball Tree； : DBSCAN 執行緩慢的主因在於尋找每個點的鄰域時需要進行大量的距離計算 (複雜度接近 O(N^2))。使用 KD-Tree 或 Ball Tree 等空間索引結構，可以將鄰居搜尋的時間複雜度降低至 O(N log N)，在不改變演算法邏輯下極大提升效率。\n\n其他選項說明：\n🔹 A. 改用以平均連結（Average Linkage）為基礎的階層式群集法（Hierarchical Clustering）； : 階層式群集法在大資料量下計算量與記憶體消耗更龐大，且違反了「不改變演算法核心邏輯」的前提。\n🔹 C. 將 ε（Epsilon）參數調得極小，以減少鄰近點的數量； : 隨意調小參數會直接破壞聚類結果的正確性，產生大量雜訊。\n🔹 D. 在資料前處理時增加標準化後的特徵維度數 : 增加特徵維度只會讓距離計算更慢，加劇維度災難與效能問題。",
