        "A": "在高維空間中，維度詛咒(Curse of Dimensionality)使得資料點之間的距離趨於相近，導致DBSCAN 的密度估計失效；",
        "B": "DBSCAN 演算法僅適用於低維資料，無法處理高維資料；",
