      "explanation": "正確答案是 B. 請求併發控制機制不佳，導致多個請求同時搶占GPU Context 資源造成延遲；。\n\n解析：\n🔹 B. 請求併發控制機制不佳，導致多個請求同時搶占GPU Context 資源造成延遲； : 在未妥善管理併發的情況下，大量請求會導致 GPU 在切換 Context 時產生極大的開銷（Thrashing），使得整體吞吐量反而下降、延遲飆高。\n\n其他選項說明：\n🔹 A. GPU 排程策略與批次大小設定不當，導致GPU 運算單元未被有效利用； : 雖然會影響吞吐量，但通常不會是造成服務連鎖壅塞崩潰的最致命原因。\n🔹 C. GPU 硬體效能不足，無法支撐推論負載； : 僅硬體不足應會表現為平穩的低吞吐，而非因機制不佳引發的資源搶占崩潰。\n🔹 D. 模型未進行量化優化，導致推論計算成本過高 D : 未量化只會使得基準延遲較高，不會解釋為何在併發環境下系統會產生預期外的延遲雪崩。"
