      "explanation": "正確答案是 B. 為外部服務導入斷路器模式(Circuit Breaker)，在異常時暫停呼叫並提供替代回應；。\n\n解析：\n🔹 B. 為外部服務導入斷路器模式(Circuit Breaker)，在異常時暫停呼叫並提供替代回應； : 斷路器（Circuit Breaker）能自動偵測下游服務的超時或故障，及時阻斷請求以避免資源耗盡，是微服務架構中防止連鎖故障（Cascading Failure）的最佳設計。\n\n其他選項說明：\n🔹 A. 將所有外部API 呼叫改為同步串行處理，並取消逾時限制，確保每個請求皆完成後再繼續； : 取消逾時限制會導致執行緒無限期卡死，加速平台整體服務崩潰。\n🔹 C. 擴充各微服務的執行緒池(Thread Pool)上限，以提升併發處理能力； : 當外部服務緩慢時，盲目擴充執行緒只會讓更多資源被積壓，最終拖垮記憶體與 CPU，無法解決根本阻塞。\n🔹 D. 停用服務健康檢查，減少不必要的額外負載 C : 停用健康檢查會讓負載平衡器將流量導向已故障的節點，反而使問題更嚴重。"
