        "C": "將資料輸出為CSV，再以Excel 的STDEV 函數計算；",
        "D": "使用DataFrame.agg({'col': 'stddev'})或RDD.aggregate()等分散式統計方法，由各Executor 計算局部統計量後再進行彙總"
