      "id": "subject2_new_76",
      "explanation": "正確答案是 C. [\"checked\", \"checked\"] ；\n\n解析：\n🔹 C. [\"checked\", \"checked\"] ； : 在 Python 中，函式的預設參數（如 `tags=[]`）只會在函式定義時被評估與建立一次。因為 list 是可變物件 (mutable)，當 row1 呼叫並附加了 \"checked\" 後，該預設 list 就被修改了。接著 row2 呼叫時使用的是同一個 list，再次附加 \"checked\"，所以結果會變成 `[\"checked\", \"checked\"]`。\n\n其他選項說明：\n🔹 A. [\"checked\", \"tags\"]； : 不符合 Python 預設參數的行為特性。\n🔹 B. []； : 由於 list 已經被 append 修改，不會保持為空陣列。\n🔹 D. 拋出KeyError 錯誤，因為字典中沒有tags 鍵值 Ａ : 函式設計會先處理缺值，不會直接拋出 KeyError。"
