      "options": {
        "A": "0.686；",
        "B": "0.700；",
        "C": "0.720；",
        "D": "0.750"
      },
      "answer": "A",
      "explanation": "正確答案是 A. 0.686；。\n\n解析：\n🔹 A. 0.686； : F1 Score 是精確率（Precision）與召回率（Recall）的調和平均數。計算公式為 2 * (Precision * Recall) / (Precision + Recall) = 2 * (0.8 * 0.6) / (0.8 + 0.6) = 0.96 / 1.4 ≈ 0.6857，進位為 0.686。\n\n其他選項說明：\n🔹 B. 0.700； : 這是精確率與召回率的算術平均數 (0.8+0.6)/2 = 0.7，不是 F1 Score 的計算方式。\n🔹 C. 0.720； : 計算錯誤所得的干擾值。\n🔹 D. 0.750 : 計算錯誤所得的干擾值。"
