      "explanation": "正確答案是 B. O(n²) — 執行時間與資料量平方成正比；。\n\n解析：\n🔹 B. O(n²) — 執行時間與資料量平方成正比； : 若要將每一位客戶與其他所有客戶進行兩兩比對，總共需要進行 n×(n-1)/2 次計算，這屬於 O(n²) 的時間複雜度，執行時間會隨著資料量的平方成正比增加。\n\n其他選項說明：\n🔹 A. O(n) — 執行時間與資料量成線性關係； : O(n) 僅適合掃描一次全部資料，無法涵蓋所有客戶兩兩之間的交叉比對。\n🔹 C. O(1) — 執行時間固定不變； : O(1) 代表與資料量無關的常數時間，兩兩比對必定會受資料量大小影響，不可能固定不變。\n🔹 D. O(log n) — 執行時間與資料量呈對數成長關係 : O(log n) 通常出現於二分搜尋等分治法，與全面性的兩兩組合比對邏輯不符。"
