      "explanation": "正確答案是 A. for param in model.features.parameters(): param.requires_grad = False；\n\n解析：\n🔹 A. for param in model.features.parameters(): param.requires_grad = False； : 在 PyTorch 中的 VGG 模型，卷積層特徵提取部分通常稱為 `features`。透過將其參數的 `requires_grad` 設為 False 即可凍結這部分的參數。\n\n其他選項說明：\n🔹 B. for param in model.classifier.parameters(): param.requires_grad = False； : 這會凍結分類層（全連接層），與題目要求的「只訓練最後全連接層」背道而馳。\n🔹 C. for param in model.parameters(): param.requires_grad = True； : 這會讓所有參數都參與訓練，而非凍結卷積層。\n🔹 D. model.features.requires_grad = False : 在 PyTorch 中無法直接對模組設定 requires_grad，必須針對模組內的參數迭代設定。"
