      "explanation": "正確答案是 A. 同時結合一階動量(Momentum)與自適應學習率(Adaptive Learning Rate)，為每個參數調整更新步長；\n\n解析：\n🔹 A. 同時結合一階動量(Momentum)與自適應學習率(Adaptive Learning Rate)，為每個參數調整更新步長； : Adam 優化器的核心機制就是結合了 RMSProp 的自適應學習率與 Momentum 動量機制，能針對不同參數自動調節步伐，有效解決震盪與收斂緩慢問題。\n\n其他選項說明：\n🔹 B. 強制所有參數使用相同學習率(Learning Rate)，避免梯度差異造成不穩定； : 這是基本 SGD 的做法，Adam 的優勢正是「不」強制使用相同學習率。\n🔹 C. 透過批次正規化(Batch Normalization)重新分布輸入資料； : 這是 Batch Normalization 層的作用，並非優化器本身的功能。\n🔹 D. 將梯度裁剪為固定範圍以避免梯度爆炸(Gradient Explosion) A : 這是 Gradient Clipping 的技巧，雖然有助穩定訓練，但並非 Adam 優化器的內建主要機制。"
