      "explanation": "正確答案是 B. 同態加密(Homomorphic Encryption)。\n\n解析：\n🔹 B. 同態加密(Homomorphic Encryption) : 同態加密技術允許雲端伺服器直接在密文上執行特定的數學與模型推論運算，且運算結果解密後與明文運算結果完全一致。這完美達成「資料不解密」且由「單一伺服器運算」的嚴苛隱私要求。\n\n其他選項說明：\n🔹 A. 聯邦學習(Federated Learning) : 需將模型下載至用戶端進行本地訓練以保護資料不出域，與題意「上傳資料至雲端推論」的架構完全相反。\n🔹 C. 差分隱私(Differential Privacy) : 透過在資料或查詢中加入統計雜訊來保護個體隱私，但會破壞推論資料的原始精度，不適合精確預測任務。\n🔹 D. 安全多方計算(Secure Multi-Party Computation, MPC) : 依賴多方節點互相協作並交換加密碎片進行運算，不符合題目要求由「單一雲端服務商」獨立完成的前提。"
