      "explanation": "正確答案是 C. 表示單詞 vs. 表示語句整體語意。\n\n解析：\n🔹 C. 表示單詞 vs. 表示語句整體語意 : 詞向量（如 Word2Vec）旨在將單一詞彙表示為向量，捕捉詞層級的語意與關聯；而句向量（如 SBERT 等）則是將整個句子壓縮成一個固定長度的向量，能夠捕捉上下文關係與整句的全局語意，更適合用於句子相似度計算或文本分類。\n\n其他選項說明：\n🔹 A. 長度不同 : 兩者的向量維度長度皆可由開發者設定（例如皆可設為 768 維），長度本身並非它們在概念與用途上的主要差異所在。\n🔹 B. 是否可用於圖像任務 : 兩者皆為自然語言處理（NLP）領域中將文字向量化的技術，主要應用於文字資料，與是否能用於圖像任務無關。\n🔹 D. 是否包含卷積運算 : 詞向量與句向量皆可透過多種不同的神經網路架構（如 Transformer、RNN 甚至 CNN）來學習生成，是否有卷積運算取決於所選用的底層模型，而非兩者的本質差異。"
