      "explanation": "正確答案是 C. 使用 Encoder-Only 結構。\n\n解析：\n🔹 C. 使用 Encoder-Only 結構 : BERT（Bidirectional Encoder Representations from Transformers）是由 Google 提出的預訓練語言模型。其架構僅採用了 Transformer 的編碼器（Encoder）部分，透過自注意力機制（Self-Attention）同時考慮字詞左右兩側的上下文，達成深度的雙向語意理解，特別適合用於理解型的 NLP 任務如問答系統與文本分類。\n\n其他選項說明：\n🔹 A. 採用單向上下文語意建模 : 錯誤。BERT 最大的特色就是「雙向（Bidirectional）」語意建模；採用單向（由左至右或由右至左）建模的模型代表為 GPT 系列。\n🔹 B. 用於物件辨識 : 錯誤。BERT 是自然語言處理（NLP）領域的模型，處理的是文本序列，物件辨識屬於電腦視覺（CV）領域的任務，通常使用 CNN 或 Vision Transformer（ViT）。\n🔹 D. 適合用於圖像特徵擷取 : 錯誤。如同上一點所述，BERT 專注於提取文字的語意特徵，並無法直接處理像素層級的圖像特徵擷取。"
