      "explanation": "正確答案是 C. Parameter-Efficient Tuning（如 LoRA）。\n\n解析：\n🔹 C. Parameter-Efficient Tuning（如 LoRA） : 參數高效微調技術（PEFT）透過凍結預訓練模型的大部分權重，僅訓練極少數新增或特定的參數（如 LoRA 中的低秩矩陣），從而在不更動原模型主要權重的情況下，以低運算成本快速適應下游任務。\n\n其他選項說明：\n🔹 A. SHAP : SHAP 是一種解釋機器學習模型預測結果的工具，基於賽局理論計算每個特徵對預測結果的貢獻度，與微調生成模型無關。\n🔹 B. Fine-tuning API : 傳統的全參數微調 API 會更新模型的所有權重，計算成本與時間消耗較大，不符合「不調整模型權重」的條件。\n🔹 D. Tokenization : Tokenization（斷詞）是將輸入文本轉換為模型可處理的詞彙標記的預處理步驟，並非模型微調的技術。"
