      "explanation": "正確答案是 C. 自監督學習（Self-Supervised Learning）。\n\n解析：\n🔹 C. 自監督學習（Self-Supervised Learning） : 自監督學習透過資料本身設計任務（如遮蔽詞預測、克漏字填空），讓模型在未經人工標註的資料上學習語意表示，藉此掌握語言的結構與知識。\n\n其他選項說明：\n🔹 A. 強化學習 : 強化學習是透過智能體與環境互動，根據獲得的獎勵或懲罰來優化策略，通常用於決策控制，而非直接從未標記資料中學習基礎語意。\n🔹 B. 蒸餾學習 : 知識蒸餾（Knowledge Distillation）是將大型模型（教師模型）的知識轉移到較小模型（學生模型）的技術，目的在於模型壓縮與加速，而非針對未標記資料學習語意。\n🔹 D. K-Means 聚類 : K-Means 是一種非監督式學習演算法，主要用於將資料分群，將相似特徵的樣本歸類在一起，但它無法像自監督學習那樣讓語言模型深層學習豐富的語意特徵。"
