      "explanation": "正確答案是 C. 右偏斜（右尾長）的連續變數。\n\n解析：\n🔹 C. 右偏斜（右尾長）的連續變數 : 許多真實世界的資料（如收入、交易金額）呈現高度右偏的長尾分佈。對數轉換（Log Transformation）可以大幅壓縮巨額極端值，將偏斜的分佈拉伸成更接近對稱的常態分佈，提升線性模型與參數統計的穩健性。\n\n其他選項說明：\n🔹 A. 常態分布資料 : 資料已經是常態分佈，再進行對數轉換反而會破壞其常態性。\n🔹 B. 離散類別欄位 : 類別標籤不具備連續數學意義，進行對數運算無效。\n🔹 D. 資料集中為零 : log(0) 在數學上未定義（趨近負無限大），因此含有大量零的資料需經過平移（如 log(x+1)）才能轉換。"
