      "explanation": "正確答案是 C. 差分隱私（Differential Privacy）。\n\n解析：\n🔹 C. 差分隱私（Differential Privacy） : 差分隱私透過在資料集中注入數學上精確計算的隨機噪音，確保攻擊者無法確認特定個人是否包含在資料中，實現強大的匿名保護，同時其聚合統計結果依然高度準確且具分析價值。\n\n其他選項說明：\n🔹 A. Base64 編碼 : Base64 僅是一種資料格式編碼方式，任何人都可以輕易解碼還原原始資料，完全無法提供匿名或隱私保護。\n🔹 B. AES 加密 : AES 雖然能強效保護資料不被竊取，但在未解密的情況下無法對資料進行聚合分析；一旦解密，資料便失去匿名性。\n🔹 D. Hash 值比對 : 雖然 Hash 函數為單向不可逆，但無法防止彩虹表或字典攻擊來反推出常見的原始資料，且 Hash 後的資料無法進行聚合統計分析。"
