      "explanation": "正確答案是 C. 說明若輸入資料略為改變，預測結果將如何變化。\n\n解析：\n🔹 C. 說明若輸入資料略為改變，預測結果將如何變化 : 反事實解釋（Counterfactual Explanation）旨在回答「如果要改變目前的預測結果，使用者的特徵需要做出什麼最小的改變？」（例如：如果您的收入增加一萬元，貸款申請就會通過）。這對使用者而言具備高度的可操作性與直觀性。\n\n其他選項說明：\n🔹 A. 預測未發生事件的可能性 : 這是傳統預測模型本身的目的，並非反事實「解釋」的核心。\n🔹 B. 建構完全隨機的樣本 : 反事實解釋是尋求朝特定預測結果改變的「最小變動路徑」，而非隨機建構。\n🔹 D. 模型準確率不變時，如何壓縮模型 : 這是模型壓縮技術（如剪枝、量化）的研究範疇，與模型解釋性無關。"
